package org.simpleweather.qa;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
/** Historical pre-3.0.0-2 fixture; excluded from the current test runner. */
public final class InternalMusicMigrationTests extends Instrumentation {
    private Activity host,music;private Context c;private ClassLoader loader,ml;private int checks;
    public void onCreate(Bundle b){super.onCreate(b);start();}
    private Object call(Object o,String n,Class<?>[] types,Object...v)throws Exception{Method m=(o instanceof Class?(Class)o:o.getClass()).getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o instanceof Class?null:o,v);}
    private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
    private Class<?> type(String n)throws Exception{return Class.forName("org.simpleweather.app."+n,true,loader);}
    private void ui(Runnable r){AtomicReference<Throwable> e=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable t){e.set(t);}});if(e.get()!=null)throw new RuntimeException(e.get());waitForIdleSync();}
    private void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
    private Uri doc(String name){return DocumentsContract.buildDocumentUriUsingTree(DocumentsContract.buildTreeDocumentUri("org.simpleweather.migrationqa.documents","root"),name);}
    private byte[] bytes(Uri uri)throws Exception{try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    private void write(Uri uri,byte[] b)throws Exception{try(OutputStream out=c.getContentResolver().openOutputStream(uri,"wt")){out.write(b);}}
    public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();loader=c.getClassLoader();c.startActivity(new Intent().setClassName("org.simpleweather.migrationqa","org.simpleweather.qa.MigrationGrantActivity").putExtra("target",c.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);waitForIdleSync();c.getSharedPreferences("toolbox",0).edit().putInt("seen_version",53).commit();host=startActivitySync(new Intent().setClassName(c,"org.simpleweather.app.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object apps=field(host,"apps");try(InputStream in=new FileInputStream("/data/local/tmp/internal-apps/music.ddapp")){call(apps,"install",new Class[]{InputStream.class,String.class,String.class},in,"music",null);}Intent intent=(Intent)call(type("ModuleRuntime"),"pageIntent",new Class[]{Context.class,String.class,String.class},c,"music","main");music=startActivitySync(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();ml=field(music,"page").getClass().getClassLoader();Class<?> migration=Class.forName("org.daidai.modules.music.MusicMigration",true,ml);SharedPreferences prefs=c.getSharedPreferences("music_module",0);prefs.edit().clear().putInt("volume_percent",33).commit();String tree=DocumentsContract.buildTreeDocumentUri("org.simpleweather.migrationqa.documents","root").toString();File file=(File)call(migration,"copyArchive",new Class[]{Context.class,Uri.class},music,doc("migration.zip"));
        Object summary=call(migration,"inspect",new Class[]{File.class},file);check((Integer)field(summary,"songs")==2,"two same-name songs exported");check((Integer)field(summary,"playlists")==1,"playlist count");check((Integer)field(summary,"lyrics")==1&&(Integer)field(summary,"artwork")==1,"lyrics and private artwork exported");
        Object canceled=call(migration,"prepare",new Class[]{Context.class,File.class,String.class},music,file,tree);call(canceled,"close",new Class[]{});check(prefs.getInt("volume_percent",0)==33,"cancel preserves current data");
        byte[] original=bytes(doc("migration-tagged.mp3"));write(doc("migration-tagged.mp3"),new byte[]{1,2,3});boolean rejected=false;try{call(migration,"prepare",new Class[]{Context.class,File.class,String.class},music,file,tree);}catch(InvocationTargetException expected){rejected=true;}finally{write(doc("migration-tagged.mp3"),original);}check(rejected,"changed audio rejected");check(prefs.getInt("volume_percent",0)==33,"failed import leaves current preferences");
        Object prepared=call(migration,"prepare",new Class[]{Context.class,File.class,String.class},music,file,tree);call(prepared,"commit",new Class[]{Context.class},music);call(prepared,"close",new Class[]{});check(prefs.getInt("volume_percent",0)==17,"settings migrated");JSONArray rows=new JSONArray(prefs.getString("catalogue","[]"));check(rows.length()==2,"both songs retained");check(rows.getJSONObject(0).getString("title").equals(rows.getJSONObject(1).getString("title")),"duplicate display names allowed");check(!rows.getJSONObject(0).getString("uri").equals(rows.getJSONObject(1).getString("uri")),"file identities remain distinct");JSONObject row=rows.getJSONObject(0);check(row.getString("bpm").equals("123.45")&&row.getInt("rating")==8,"BPM and rating retained");check(row.getString("composer").contains("Composer B")&&row.getString("notes").equals("Migration notes"),"credits and notes retained");check(new File(row.getString("coverPath")).isFile(),"artwork relinked to internal private data");check(new String(Files.readAllBytes(new File(row.getString("lrcPath")).toPath()),"UTF-8").contains("Migration lyric"),"lyric relinked");check(new JSONObject(prefs.getString("collections","{}")).getJSONArray("favorites").length()==1,"favourites retained");check(Arrays.equals(original,bytes(doc("migration-tagged.mp3"))),"original audio unchanged");
        // Reload the bound production player, play silently and leave the activity.
        Object page=field(music,"page"),service=null;for(int i=0;i<60&&service==null;i++){service=field(page,"service");Thread.sleep(50);}check(service!=null,"internal playback service bound");final Object player=service;ui(()->{try{call(player,"reload",new Class[]{});call(player,"setVolume",new Class[]{int.class},0);call(player,"play",new Class[]{int.class},0);}catch(Exception e){throw new RuntimeException(e);}});boolean playing=false;for(int i=0;i<100&&!playing;i++){playing=(Boolean)call(player,"isPlaying",new Class[]{});Thread.sleep(30);}check(playing,"migrated song actually plays");ui(()->music.finish());music=null;c.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(200);check((Boolean)call(player,"isPlaying",new Class[]{}),"playback continues after leaving internal app");ui(()->{try{call(player,"stopPlayback",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});file.delete();result.putString("result","PASS: "+checks+" cross-package same-device migration and playback checks");
    }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));result.putString("result","FAIL: "+w);}finally{if(music!=null)ui(()->music.finish());if(host!=null)ui(()->host.finish());finish(Activity.RESULT_OK,result);}}
}
